export function run(input) {
  if (!input || !Array.isArray(input.values) || !input.values.every((value) => typeof value === "number" && Number.isFinite(value))) {
    throw new TypeError("input.values must be an array of finite numbers");
  }
  return input.values.reduce((sum, value) => sum + value, 0);
}
